const $=s=>document.querySelector(s);const icons={home:'<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',squad:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 12h18M9 3v4h6V3M9 21v-4h6v4"/><circle cx="12" cy="12" r="3"/>',players:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 4v3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M7 15h3M14 15h3"/>',results:'<path d="M8 3h8v7a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4M16 5h4v3a4 4 0 0 1-4 4M12 14v6M8 21h8"/>',reviews:'<path d="m12 3 3 6 6 1-4.5 4.5L18 21l-6-3-6 3 1.5-6.5L3 10l6-1z"/>',tactics:'<circle cx="6" cy="17" r="3"/><circle cx="18" cy="6" r="3"/><path d="M6 14V5h6M9 17h9v-5M12 3l2 2-2 2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.home}</svg>`;
icons.more='<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>';
icons.shuffle='<path d="M3 6h3c6 0 6 12 12 12h3m-4-4 4 4-4 4M3 18h3c2 0 3.5-1.5 5-4m3-4c1-2 2-4 4-4h3m-4-4 4 4-4 4"/>';icons.balance='<path d="M12 3v18M5 21h14M4 7h16M6 7l-4 8h8L6 7Zm12 0-4 8h8l-4-8Z"/>';
const nav=[['home','클럽 하우스','home'],['squad','스쿼드','squad'],['players','선수단','players'],['matches','경기 일정','calendar'],['results','경기 기록','results'],['reviews','동료 평가','reviews'],['more','더보기','more'],['inhouse','자체전 팀 편성','squad']];
const players=[{id:9,name:'데모 선수',pos:'CM',role:'중앙 미드필더',secondary:[],ovr:82,goals:0,assists:0,stats:[68, 82, 83, 86, 78, 80],tone:'gold',skin:'#d6aa83',hair:'#24231e',randomStats:true}];
players.forEach(p=>{p.matchRating=p.randomStats?'—':(p.ovr/10+0.2).toFixed(1);p.demo=Abilities.demo[p.id]});
players.forEach(p=>PilotRoster.restoreExisting(p,{getItem:key=>TeamStore.getItem(key)}));
players.push(...PilotRoster.hydrate({getItem:key=>TeamStore.getItem(key)}));
const ratingText=value=>Number.isFinite(value)?String(value):'—';
const averageText=value=>Number.isFinite(value)?value.toFixed(1):'—';
let state={formation:'1-2-1',lineup:players.slice(0,5).map(p=>p.id),strategy:'balance',press:60,pace:65,width:55,reviews:{},fixtures:[]};try{const saved=JSON.parse(TeamStore.getItem('unit-fc-v1'));if(saved&&Array.isArray(saved.fixtures)){const fallback=state.lineup;state={...state,...saved};if(!Array.isArray(state.lineup)||![4,5,6,7].includes(state.lineup.length)||state.lineup.some(id=>!players.some(p=>p.id===id)))state.lineup=fallback;state.reviews=Object.fromEntries(Object.entries(state.reviews||{}).filter(([id])=>players.some(p=>p.id===Number(id))));if(state.record?.players)state.record.players=Object.fromEntries(Object.entries(state.record.players).filter(([id])=>players.some(p=>p.id===Number(id))))}}catch{}for(const review of Object.values(state.reviews)){if(review?.attributes)review.attributes=Abilities.renameDetails(review.attributes);}const save=()=>{try{TeamStore.setItem('unit-fc-v1',JSON.stringify(state))}catch{toast('브라우저 저장 공간을 사용할 수 없어 이번 방문에만 유지됩니다.')}};let filter='all',search='',reviewPlayer=101,month=11,year=2026;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const getPlayer=id=>players.find(p=>p.id===Number(id));let currentPage='home';SquadUI.init(players,state);
const head=(title,sub,action='',eyebrow='')=>`<div class="page-heading"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h1>${title}</h1><p>${sub}</p></div>${action}</div>`;const btn=(label,action,cls='',ico='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;const linkbtn=(label,page)=>`<a class="text-btn" href="#${page}">${label} <span><svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a>`;const panelhead=(title,en,link='')=>`<div class="panel-head"><h2>${title}<span>${en}</span></h2>${link}</div>`;
function portrait(p){const photo=PlayerPhotos.url(p.id,p.photo);if(photo)return `<img class="uploaded-player-photo" src="${photo}" alt="${p.name} 선수 사진">`;if(p.managed)return `<svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="34" r="20" fill="#66805b"/><path d="M12 100V86C12 53 88 53 88 86V100Z" fill="#455e3d"/></svg>`;return `<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M7 100Q5 73 32 67L68 67Q95 74 97 100Z" fill="#263a26"/><path d="M32 67 44 76 56 76 68 67 62 100H39Z" fill="#354d2c"/><path d="M17 77 28 73 34 100H21Z M72 73 84 78 80 100H66Z" fill="#a8ce64"/><path d="M42 54v16q8 9 16 0V54" fill="${p.skin}"/><ellipse cx="50" cy="39" rx="20" ry="25" fill="${p.skin}"/><path d="M29 37Q23 9 48 7Q74 6 72 35L66 28 64 22Q44 28 34 22L34 37Z" fill="${p.hair}"/><path d="M39 39h4m14 0h4M46 54q5 3 10-1" stroke="#5d4334" stroke-width="1.5" fill="none"/><path d="m49 42-2 6h5" stroke="#a47156" fill="none"/></svg>`}
function card(p){const attributes=Abilities.schema(p),injured=PlayerTraits.read(TeamStore,p.id).status==='injured';return `<button class="player-card stats-card online-card ${p.pos==='GK'?'keeper-card':''}" data-action="player" data-id="${p.id}" aria-label="${p.name}${injured?' 부상,':''} ${p.pos} 종합 능력치 ${ratingText(p.ovr)}, ${attributes.map((a,i)=>`${a[1]} ${ratingText(p.stats[i])}`).join(', ')}. 상세 보기"><img class="card-frame" src="assets/player-card-gold-v2.png" alt="" aria-hidden="true"><span class="card-edition">FUTSAL LEAGUE</span><div class="card-rating"><span class="ovr-number">${ratingText(p.ovr)}</span><small>${p.pos}</small></div><div class="card-person">${portrait(p)}</div><strong class="card-name">${p.name}</strong><div class="card-stats">${p.stats.map((v,i)=>`<div title="${attributes[i][1]} ${ratingText(v)}"><span>${attributes[i][0]}</span><b>${ratingText(v)}</b></div>`).join('')}</div><div class="card-badges"><img class="card-national-flag" src="assets/korea-flag.png" alt="대한민국 태극기"><span class="unit-card-logo" role="img" aria-label="리그 로고"></span>${ClubSettings.cardEmblem()}</div>${injured?'<span class="card-injury-badge" aria-hidden="true"><span class="card-injury-word">부상</span></span>':''}</button>`}

function pitch(big=false){return SquadUI.pitch(big)}
function matchContent(){return `<div class="match-top"><span class="tag">친선 경기</span><span class="match-date">11.07 (토) · 14:00</span></div><div class="match-versus"><div class="team"><div class="crest">U</div><strong>${ClubSettings.html('name')}</strong><small>우리 팀 · HOME</small></div><div class="versus">VS<small>D-6</small></div><div class="team"><div class="crest away">B</div><strong>청룡 FC</strong><small>AWAY TEAM</small></div></div><div class="match-meta">${icon('pin')} 제1풋살장 <span class="time">${icon('clock')}</span> 60분</div>${btn('경기 상세 보기','match-detail','secondary','arrow')}`}
const stadium=`<img src="assets/hero-football-pitch.svg?v=1" width="640" height="390" alt="" decoding="async" draggable="false">`;
function home(){const known=players.filter(p=>Number.isFinite(p.ovr));return `<div class="mobile-greeting"><div><span class="eyebrow">OUR TEAM</span><h1>오늘도, 함께 뛰자<span class="lime">.</span></h1><p>${ClubSettings.html('name')} · 함께 뛰는 우리 팀</p></div></div><section class="mobile-hero"><div><span class="eyebrow">OUR TEAM. OUR GAME.</span><h2>ONE TEAM.<br><span>ONE PASSION.</span></h2><a href="#squad" class="btn">스쿼드 구성 ${icon('arrow')}</a></div><div class="mobile-hero-art">${stadium}</div><span class="hero-serial">${ClubSettings.html('name')}</span></section><div class="mobile-stats"><a href="#players"><span>등록 선수</span><strong>${players.length}<small>명</small></strong></a><a href="#players"><span>OVR 입력</span><strong>${known.length}<small>명</small></strong></a><a href="#players"><span>OVR 입력 대기</span><strong>${players.length-known.length}<small>명</small></strong></a></div><section class="panel">${panelhead('우리 팀 선수','TEAM ROSTER',linkbtn('선수단 관리','players'))}<div class="panel-body"><p class="note">선수 카드에서 사진과 신체 정보, 포지션과 능력치를 직접 입력하세요.</p><a class="btn wide" href="#players">선수 카드 관리 ${icon('arrow')}</a></div></section><section class="reveal-home"><span class="eyebrow">PLAYER REVEAL</span><h3>우리 팀의 카드를 열다.</h3><p>선수와 함께하는 우리 리그의 특별한 순간.</p><button class="btn" data-action="reveal-picker">선수 카드 공개 ↗</button></section><div class="quick-links"><a href="#reviews">${icon('reviews')}<span>동료 평가</span><b><svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></b></a><a href="#squad">${icon('squad')}<span>포메이션 · 자유 배치</span><b><svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></b></a></div><section class="panel">${panelhead('경기 기록','MATCH RECORD',linkbtn('전체 기록','results'))}<div class="panel-body"><p class="note">${state.record?`${esc(state.record.opponent)} · ${esc(state.record.score)}`:'아직 입력한 경기 기록이 없습니다.'}</p>${btn('경기 기록 입력','record-match','secondary')}</div></section>`}

function squad(){return SquadUI.page()}
function playersPage(){let list=players.filter(p=>(filter==='all'||Abilities.group(p.pos)===filter)&&p.name.includes(search)).sort((a,b)=>Number(Boolean(b.managed))-Number(Boolean(a.managed)));return `${head('선수단','우리 팀의 선수 프로필을 직접 관리하세요.',`<span class="tag">등록 선수 ${players.length}명</span>`,'MEET THE SQUAD')}<div class="pilot-roster-note"><strong>선수 프로필 · 관리자 직접 등록</strong>등록 선수 ${players.length}명<br>선수별 ‘스탯 입력’을 눌러 포지션과 능력치를 설정하세요.</div><div class="toolbar"><div class="tabs">${[['all','전체'],['attack','공격수'],['midfield','미드필더'],['defense','수비수'],['GK','골키퍼']].map(([v,l])=>`<button class="tab ${filter===v?'active':''}" data-action="filter" data-value="${v}">${l}</button>`).join('')}</div><input class="search" id="player-search" type="search" aria-label="선수 이름 검색" placeholder="선수 이름 검색" value="${esc(search)}"></div><p class="ability-legend">${filter==='GK'?'REF 반사신경 · POS 위치 선정 · 1V1 1대1 방어<br>HAN 핸들링 · BLD 빌드업':'PAC 스피드 · SHO 슈팅 · PAS 패스<br>DRI 드리블 · DEF 수비 · PHY 피지컬'}<br><span>필드 6대 분류 / ${Abilities.field.reduce((n,a)=>n+a[2].length,0)}항목 · GK 5대 분류 / ${Abilities.keeper.reduce((n,a)=>n+a[2].length,0)}항목 · 미입력 값은 —</span></p><div class="players-grid">${list.length?list.map(p=>`<article class="player-tile">${card(p)}<strong>${p.name}</strong><small>${p.role} · ${ClubSettings.html('name')}</small>${p.managed?`<button class="btn secondary pilot-card-edit" data-action="pilot-edit" data-id="${p.id}">스탯 ${PilotRoster.complete(p)?'수정':'입력'}</button>`:`<div class="tile-bottom"><span><b>${p.goals}</b>득점</span><span><b>${p.assists}</b>도움</span><span><b>${p.matchRating}</b>평점</span></div>`}</article>`).join(''):'<div class="empty-state">검색 결과가 없습니다. 다른 이름을 입력해 주세요.</div>'}</div>`}
const baseFixtures=[{date:'2026-11-07',time:'14:00',opponent:'청룡 FC',venue:'제1풋살장',type:'친선 경기',duration:'60'},{date:'2026-11-14',time:'15:00',opponent:'번개 FC',venue:'번개 풋살 파크',type:'교류전',duration:'60'},{date:'2026-11-21',time:'10:00',opponent:'독수리 FC',venue:'실내 풋살장',type:'친선 경기',duration:'90'}];const fixtures=()=>[...baseFixtures,...state.fixtures].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
function matches(){const fs=fixtures();const offset=new Date(year,month-1,1).getDay(),days=new Date(year,month,0).getDate();const inMonth=fs.filter(f=>f.date.startsWith(`${year}-${String(month).padStart(2,'0')}`));return `${head('경기 일정','다음 경기도, 우리답게.',btn('경기 만들기','create-match','','plus'),'MATCH DAY')}<section class="panel phone-calendar">${panelhead(`${year}년 ${month}월`,'',`<div class="calendar-controls"><button class="icon-btn" data-action="prev-month" aria-label="이전 달">←</button><button class="icon-btn" data-action="next-month" aria-label="다음 달">→</button></div>`)}<div class="month-grid">${['일','월','화','수','목','금','토'].map(d=>`<span class="week-name">${d}</span>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const date=`${year}-${String(month).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,events=fs.filter(f=>f.date===date);return events.length?`<button class="month-day has-match" data-action="day-fixtures" data-date="${date}" aria-label="${month}월 ${i+1}일 경기 ${events.length}개"><span>${i+1}</span><i></i></button>`:`<span class="month-day ${date==='2026-11-01'?'is-today':''}"><span>${i+1}</span></span>`}).join('')}</div><div class="calendar-legend"><i></i> 경기 있는 날 <span>오늘</span> 11월 1일</div></section><div class="mobile-section-label"><h2>예정된 경기</h2><span>${inMonth.length}경기</span></div><div class="fixture-list">${inMonth.map(f=>`<button class="fixture-card" data-action="fixture" data-id="${fs.indexOf(f)}"><div class="fixture-date"><strong>${Number(f.date.slice(8))}</strong><span>${['일','월','화','수','목','금','토'][new Date(f.date+'T12:00').getDay()]}요일</span></div><div class="fixture-info"><span class="tag">${esc(f.type)}</span><strong>vs ${esc(f.opponent)}</strong><small>${esc(f.time)} · ${esc(f.venue)}</small></div><span class="fixture-arrow"><svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></button>`).join('')||'<div class="empty-state">아직 예정된 경기가 없어요.<br>첫 경기를 만들어 보세요.</div>'}</div><p class="prototype-note">데모 일정입니다. 실제 구장 예약이나 상대 팀 연락은 진행되지 않습니다.</p>`}

function results(){const record=state.record;return `${head('경기 기록','직접 입력한 경기와 우리 선수들의 기록입니다.',btn('기록 입력','record-match','secondary','plus'),'EVERY GAME COUNTS')}${record?`<div class="summary-box"><strong>${ClubSettings.html('name')} ${esc(record.score)} ${esc(record.opponent)}</strong>${esc(record.notes||'')}</div><section class="panel">${panelhead('선수별 경기 기록','MATCH RECORD')}<div class="table-wrap"><table><thead><tr><th>선수</th><th>득점</th><th>도움</th></tr></thead><tbody>${players.map(p=>`<tr><td><button class="text-btn" data-action="player" data-id="${p.id}">${p.name}</button></td><td>${record.players?.[p.id]?.goals??'—'}</td><td>${record.players?.[p.id]?.assists??'—'}</td></tr>`).join('')}</tbody></table></div></section>`:'<section class="panel"><div class="empty-state">아직 입력한 경기 기록이 없습니다.<br>첫 경기의 결과와 선수별 기록을 남겨 주세요.</div></section>'}<p class="prototype-note">경기 기록은 이 브라우저에 저장됩니다.</p>`}

function reviews(){const p=getPlayer(reviewPlayer),saved=state.reviews[p.id],attributes=Abilities.schema(p);return `${head('동료 평가','함께 뛴 동료의 플레이를 돌아보세요.','','GROW TOGETHER')}<div class="inline-info">경기 후 반영 · 세부 항목을 관찰한 만큼 평가하세요.<br>1 낮음 · 3 보통 · 5 뛰어남 · 관찰하지 못한 항목은 평가하지 않음</div><div class="review-grid"><section class="panel">${panelhead('평가할 동료 선택','TEAMMATE REVIEW')}${players.filter(p=>p.id!==9).map(p=>`<button class="review-choice ${p.id===reviewPlayer?'selected':''}" data-action="review-select" data-id="${p.id}"><div><strong>${p.name}</strong><small>${p.pos} · ${p.role}</small></div><span class="tag">${state.reviews[p.id]?.schema===2?'평가 완료':'평가 대기'}</span></button>`).join('')}</section><section class="panel">${panelhead(`${p.name} 선수의 플레이`,'YOUR FEEDBACK')}<form id="review-form" class="panel-body"><p class="note">${p.pos==='GK'?`골키퍼 5대 분류 · ${Abilities.keeper.reduce((n,a)=>n+a[2].length,0)}개`:`6대 분류 · ${attributes.reduce((n,a)=>n+a[2].length,0)}개`} 세부 항목 · 예시 경기의 동료 평가</p>${attributes.map((a,i)=>`<details class="review-group" ${i===0?'open':''}><summary><b>${a[0]}</b> ${a[1]} <span>${a[2].length}항목</span></summary>${a[2].map(label=>`<label class="review-attribute"><span>${label}${Abilities.descriptions[label]?`<small class="pilot-stat-help">${Abilities.descriptions[label]}</small>`:''}</span><select name="ability:${label}" aria-label="${label} 평가">${[['','평가하지 않음'],['1','1 · 낮음'],['2','2 · 아쉬움'],['3','3 · 보통'],['4','4 · 좋음'],['5','5 · 뛰어남']].map(([v,l])=>`<option value="${v}" ${saved?.schema===2&&saved.attributes[label]===v?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}</details>`).join('')}<label class="field">동료에게 한마디<textarea name="comment" rows="3" maxlength="300" placeholder="좋았던 플레이와 응원을 남겨 주세요.">${esc(saved?.comment||'')}</textarea></label><button type="submit" class="btn wide">평가 저장 · 반영 흐름 보기 ${icon('arrow')}</button><p class="prototype-note">데모 저장이며 실제 능력치에 반영되지 않습니다.</p></form></section></div>`}

let inhouseDraft=null;
function getInhouseDraft(){
  if(inhouseDraft)return inhouseDraft;
  const s=state.inhouse,known=new Set(players.map(p=>p.id));
  if(s&&Array.isArray(s.selected)&&s.selected.every(id=>known.has(id))&&new Set(s.selected).size===s.selected.length){
    let result=s.result;
    const assigned=result&&Array.isArray(result.a)&&Array.isArray(result.b)?[...result.a,...result.b]:[];
    if(!result||!Array.isArray(result.a)||!Array.isArray(result.b)||result.a.length<2||result.b.length<2||assigned.length!==s.selected.length||new Set(assigned).size!==assigned.length||assigned.some(id=>!s.selected.includes(id)))result=null;
    inhouseDraft={selected:[...s.selected],result:result?{a:[...result.a],b:[...result.b],mode:result.mode}:null,positions:{...s.positions},saved:true};
  }else inhouseDraft={selected:players.map(p=>p.id),result:null,positions:{},saved:false};
  return inhouseDraft;
}
function squadModes(active){return `<div class="squad-modes" aria-label="스쿼드 유형"><a href="#squad" ${active==='squad'?'class="active" aria-current="page"':''}>대외 경기 스쿼드</a><a href="#inhouse" ${active==='inhouse'?'class="active" aria-current="page"':''}>자체전 팀 편성</a></div>`}
function inhouseRoster(){return Abilities.forPositions(players,getInhouseDraft().positions);}
function inhouse(){
  const d=getInhouseDraft(),n=d.selected.length,result=d.result,assigned=inhouseRoster(),gks=d.selected.filter(id=>assigned.find(p=>p.id===id).pos==='GK').length;
  const sa=result?TeamBuilder.summarize(result.a,assigned):null,sb=result?TeamBuilder.summarize(result.b,assigned):null;
  return `${head('자체전 팀 편성','오늘은 같은 팀에서, 서로의 상대가 되어.','','PLAY EACH OTHER')}${squadModes('inhouse')}
  <section class="panel participant-panel">${panelhead('오늘 함께 뛸 선수','SELECT YOUR PLAYERS',`<button class="text-btn" data-action="inhouse-all">${n===players.length?'전체 해제':'전체 선택'}</button>`)}
  <div class="participant-summary"><strong><b>${n}</b> / ${players.length}명 참가</strong><span>${n>=4?`${Math.ceil(n/2)} vs ${Math.floor(n/2)}`:'최소 4명 선택'}</span></div>
  <div class="participant-grid">${assigned.map(p=>`<div class="participant-position"><button class="participant ${d.selected.includes(p.id)?'selected':''}" data-action="inhouse-toggle" data-id="${p.id}" aria-pressed="${d.selected.includes(p.id)}" aria-label="${p.name} 참가 선택"><span class="participant-check">${d.selected.includes(p.id)?'✓':'+'}</span><span class="participant-name"><strong>${p.name}</strong><small>${p.pos}</small></span><b class="participant-ovr">${ratingText(p.ovr)}</b></button><label>배치 포지션<select data-inhouse-position="${p.id}" aria-label="${p.name} 배치 포지션">${Object.keys(PilotRoster.positions).map(pos=>`<option value="${pos}" ${pos===p.pos?'selected':''}>${pos}</option>`).join('')}</select></label></div>`).join('')}</div>
  <div class="inhouse-notice">${n<4?'참가 선수를 4명 이상 선택하면 팀을 만들 수 있어요.':n%2?'홀수 인원이라 한 팀이 1명 더 많습니다. 교체 선수를 번갈아 운영하거나 짝수로 선택하세요.':`${n}명 모두 중복 없이 두 팀에 배정됩니다.`}</div></section>
  <p class="pilot-unrated-note">${d.selected.some(id=>!Number.isFinite(assigned.find(p=>p.id===id).ovr))?'미입력 OVR이 있습니다. 랜덤 편성은 바로 가능하며, 균형 편성은 참가 선수의 OVR을 입력한 뒤 사용할 수 있습니다.':''}</p><div class="build-buttons"><button class="btn" data-action="inhouse-build" data-mode="balanced" ${n<4?'disabled':''}>${icon('balance')}균형 맞춰 편성</button><button class="btn secondary" data-action="inhouse-build" data-mode="random" ${n<4?'disabled':''}>${icon('shuffle')}${result?'랜덤 다시 뽑기':'랜덤 편성'}</button></div>
  <p class="build-explainer">균형 편성은 선택한 배치 포지션의 OVR로 평균 차이를 최소화합니다.<br>골키퍼가 여러 명이면 나누고, 동점일 때 포지션 분포를 고려합니다.</p>
  ${result?`<section class="inhouse-result" id="inhouse-result" aria-label="자체전 편성 결과"><div class="mobile-section-label"><h2>오늘의 두 팀</h2><span class="tag">${result.mode==='balanced'?'균형 편성':result.mode==='random'?'랜덤 편성':'직접 조정'}</span></div><div class="team-comparison"><div class="compare-a"><span>TEAM A</span><strong>${averageText(sa.average)}</strong><small>${sa.count}명 · 평균 OVR</small></div><div class="team-gap"><span>평균 차이</span><b>${sa.average==null||sb.average==null?'—':Math.abs(sa.average-sb.average).toFixed(1)}</b><small>${n%2?'인원 차이 1명':'동일 인원'}</small></div><div class="compare-b"><span>TEAM B</span><strong>${averageText(sb.average)}</strong><small>${sb.count}명 · 평균 OVR</small></div><div class="strength-bar"><i style="width:${sa.average==null||sb.average==null?50:sa.average/(sa.average+sb.average)*100}%"></i></div></div>
  <div class="inhouse-teams">${[['a','A','라임'],['b','B','블루']].map(([key,label,color])=>`<section class="inhouse-team team-${key}"><header><span><i></i> TEAM ${label}</span><small>${color} · ${result[key].length}명</small></header>${result[key].map(id=>{const p=assigned.find(p=>p.id===id);return `<button class="inhouse-player" data-action="inhouse-swap" data-id="${id}" data-team="${key}" aria-label="${p.name} 다른 팀 선수와 교환"><span><strong>${p.name}</strong><small>${p.pos}</small></span><b>${ratingText(p.ovr)}</b></button>`}).join('')}<footer>총 OVR <b>${ratingText(TeamBuilder.summarize(result[key],assigned).total)}</b></footer></section>`).join('')}</div><p class="swap-hint">${icon('shuffle')} 선수를 누르면 상대 팀 선수와 맞교환할 수 있어요.</p>${gks<2?`<div class="keeper-note">${gks===1?'전문 골키퍼가 1명입니다.':'전문 골키퍼가 없습니다.'} 양 팀 골키퍼는 번갈아 맡아주세요.</div>`:''}<button class="btn wide save-inhouse" data-action="inhouse-save">${icon('squad')}${d.saved?'저장된 편성':'이 편성 저장하기'}</button><p class="prototype-note">저장한 편성은 이 브라우저에서 다시 확인할 수 있습니다.</p></section>`:`<section class="inhouse-empty"><span>${icon('balance')}</span><strong>라이벌은 가까이에.</strong><p>참가 선수를 고르고 편성 방식을 선택해 주세요.<br>우리 팀 안에서 새로운 조합이 시작됩니다.</p></section>`}`;
}
function makeInhouseTeams(mode){const d=getInhouseDraft();try{let next=TeamBuilder.build(d.selected,inhouseRoster(),mode);
  // Reroll must change the grouping, not merely exchange A and B labels.
  if(mode==='random'&&d.result){const same=(a,b)=>a.length===b.length&&a.every(id=>b.includes(id));let count=0;while((same(next.a,d.result.a)||same(next.a,d.result.b))&&count++<12)next=TeamBuilder.build(d.selected,inhouseRoster(),mode);if(same(next.a,d.result.a)||same(next.a,d.result.b))[next.a[0],next.b[0]]=[next.b[0],next.a[0]];}
  d.result=next;d.saved=false;render();document.getElementById('inhouse-result').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});toast(mode==='balanced'?'능력치를 맞춰 두 팀을 편성했습니다.':'새로운 랜덤 조합을 만들었습니다.');
}catch(error){toast(error.message)}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action^="inhouse-"]');if(!el)return;const d=getInhouseDraft(),id=Number(el.dataset.id);switch(el.dataset.action){
case'inhouse-toggle':d.selected=d.selected.includes(id)?d.selected.filter(x=>x!==id):players.filter(p=>d.selected.includes(p.id)||p.id===id).map(p=>p.id);d.result=null;d.saved=false;render();break;
case'inhouse-all':d.selected=d.selected.length===players.length?[]:players.map(p=>p.id);d.result=null;d.saved=false;render();break;
case'inhouse-build':makeInhouseTeams(el.dataset.mode);break;
case'inhouse-save':if(!d.result)return;state.inhouse={selected:[...d.selected],positions:{...d.positions},result:{a:[...d.result.a],b:[...d.result.b],mode:d.result.mode}};save();d.saved=true;render();toast('자체전 편성을 이 브라우저에 저장했습니다.');break;
case'inhouse-swap':{if(!d.result)return;const team=el.dataset.team,other=team==='a'?'b':'a';modal('상대 팀 선수와 맞교환',`<p class="note"><strong>${getPlayer(id).name}</strong> 선수와 바꿀 상대 팀 선수를 선택하세요.<br>교환하면 양 팀의 평균 능력치가 다시 계산됩니다.</p><div class="swap-options">${d.result[other].map(pid=>{const p=inhouseRoster().find(p=>p.id===pid);return `<button data-action="inhouse-confirm-swap" data-id="${id}" data-other="${pid}" data-team="${team}"><span><strong>${p.name}</strong><small>${p.pos}</small></span><b>${ratingText(p.ovr)}</b><span class="tag">교환</span></button>`}).join('')}</div>`);break;}
case'inhouse-confirm-swap':{if(!d.result)return;const team=el.dataset.team,other=team==='a'?'b':'a',otherId=Number(el.dataset.other),a=d.result[team].indexOf(id),b=d.result[other].indexOf(otherId);if(a<0||b<0)return;[d.result[team][a],d.result[other][b]]=[d.result[other][b],d.result[team][a]];d.result.mode='manual';d.saved=false;closeModal();render();toast('두 선수를 맞교환했습니다.');break;}
}});

function more(){return `${head('우리 클럽','경기 밖에서도, 하나의 팀.','','MY CLUB')}${ClubSettings.identity()}<div class="more-links">${[['results','경기 기록','우리 팀이 함께 만든 순간','results'],['reviews','동료 평가','서로의 플레이를 돌아보기','reviews'],['squad','포메이션 · 자유 배치','인원별 기본 포메이션과 직접 배치','squad']].map(([key,label,sub,ico])=>`<a href="#${key}"><span class="more-icon">${icon(ico)}</span><span><strong>${label}</strong><small>${sub}</small></span>${key==='reviews'?`<b class="tag">${Math.max(0,players.length-1-Object.values(state.reviews).filter(r=>r.schema===2).length)}</b>`:'<b><svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></b>'}</a>`).join('')}<a href="futsal.html" class="futsal-link"><span class="more-icon">${icon('squad')}</span><span><strong>풋살 매치 3D</strong><small>우리 선수 능력치로 뛰는 5대5 경기 · 미리보기</small></span><b><svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></b></a><button data-action="profile"><span class="more-icon">${icon('players')}</span><span><strong>내 선수 프로필</strong><small>데모 선수 · 프로필 관리 · CM</small></span><b><svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></b></button></div><div class="club-motto">PLAY AS ONE.<p>함께 뛰는 순간, 우리는 하나가 된다.</p></div><p class="prototype-note">우리 팀의 기록을 함께 관리합니다.<br>관리자의 변경 사항은 팀 공유 저장소에 저장됩니다.</p>`}
function bottomNav(){const active=currentPage==='inhouse'?'squad':['results','reviews','tactics','more'].includes(currentPage)?'more':currentPage;$('#bottom-nav').innerHTML=[['home','홈','home'],['squad','스쿼드','squad'],['players','선수단','players'],['matches','경기','calendar'],['more','더보기','more']].map(([key,label,ico])=>`<a href="#${key}" ${active===key?'class="active" aria-current="page"':''}>${icon(ico)}<span>${label}</span>${key==='more'&&Object.values(state.reviews).filter(r=>r.schema===2).length<players.length-1?'<i></i>':''}</a>`).join('')}
function render(){SquadUI.refresh();currentPage=location.hash.slice(1)||'home';if(currentPage==='tactics'){currentPage='squad';history.replaceState(null,'','#squad');}if(!nav.some(n=>n[0]===currentPage))currentPage='home';$('#nav').innerHTML=nav.map(([key,label,ico])=>`<a href="#${key}" class="${key===currentPage?'active':''}" ${key===currentPage?'aria-current="page"':''}>${icon(ico)}${label}${key==='reviews'?`<span class="badge">${players.length-1-Object.values(state.reviews).filter(r=>r.schema===2).length}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=nav.find(n=>n[0]===currentPage)[1];document.title=`${ClubSettings.name()} — ${$('#breadcrumb').textContent}`;$('#main').innerHTML=({home,squad,players:playersPage,matches,results,reviews,more,inhouse}[currentPage])();document.body.classList.remove('menu-open');document.body.dataset.page=currentPage;bottomNav();ClubSettings.sync();window.AppLoading?.prepare($('#main'));}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function modal(title,body){$('#modal').classList.remove('photo-editor-modal');$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button data-action="close" aria-label="닫기">×</button></div>${body}`;$('#modal').showModal();$('#modal').scrollTop=0;document.body.classList.add('sheet-open');window.AppLoading?.prepare($('#modal'));}
$('#modal').addEventListener('close',()=>document.body.classList.remove('sheet-open'));
function closeModal(){window.AppLoading?.cancel($('#modal'));if(typeof clearPhotoDraft==='function')clearPhotoDraft();$('#modal').close();document.body.classList.remove('sheet-open')}$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function playerModal(id,tab='stats',role){if(getPlayer(id)?.managed)return pilotPlayerModal(id);const p=getPlayer(id),attributes=Abilities.schema(p),selectedRole=role||p.demo.role;let offset=0;const detail=attributes.map(a=>{const values=p.demo.detail.slice(offset,offset+a[2].length);offset+=a[2].length;return `<section class="detail-stat-group"><h3><span>${a[0]}</span>${a[1]}</h3>${a[2].map((label,i)=>`<div class="detail-stat-row"><span>${label}</span><b>${values[i]}</b><i style="--stat:${values[i]}%"></i></div>`).join('')}</section>`}).join('');if($('#modal').open)closeModal();modal('선수 상세',`<div class="profile-card-head">${card(p)}<span class="demo-caption">${p.randomStats?'무작위 예시 능력치 · 임시 포지션 CM':'선수 능력치 · UI 예시'}</span></div><div class="player-photo-actions"><button class="btn secondary" data-action="photo-edit" data-id="${id}">${PlayerPhotos.url(id,getPlayer(id)?.photo)?'사진 교체':'선수 사진 등록'}</button>${PlayerPhotos.url(id,getPlayer(id)?.photo)?`<button class="text-btn" data-action="photo-remove" data-id="${id}">사진 삭제</button>`:''}</div><div class="profile-identity"><div><h2>${p.name} <span>${p.pos}</span></h2><p>${p.role}${p.secondary.length?` · 부 포지션 ${p.secondary.join(' / ')}`:''}</p></div></div>${playerInfoPanel(p)}<div class="profile-tabs" aria-label="선수 상세 메뉴">${[['stats','세부 능력치'],['roles','OVR 기준'],['updates','경기 후 반영']].map(([key,label])=>`<button class="${key===tab?'active':''}" aria-pressed="${key===tab}" data-action="profile-tab" data-id="${id}" data-value="${key}">${label}</button>`).join('')}</div>${tab==='stats'?`<div class="ratings-heading"><strong>${p.pos==='GK'?'골키퍼 전용 능력치':'6대 분류 · 세부 능력치'}</strong><span>${attributes.reduce((n,a)=>n+a[2].length,0)}항목 · 예시</span></div><div class="detail-stat-groups">${detail}</div>`:tab==='roles'?`<p class="note">축구식 포지션을 풋살 역할에 연결한 UI 기준입니다. 역할을 누르면 OVR 예시와 중점 항목을 확인할 수 있습니다.</p><div class="role-picker">${(p.pos==='GK'?['GK']:['PIV','ALA','FIX']).map(r=>`<button class="${r===selectedRole?'active':''}" data-action="profile-role" data-id="${id}" data-value="${r}" aria-pressed="${r===selectedRole}"><strong>${r}</strong>${Abilities.roles[r].name}</button>`).join('')}</div><div class="ovr-preview"><div><small>${selectedRole} 역할 OVR 예시</small><strong>${p.demo.ovrs[selectedRole]}</strong></div><p>${Abilities.roles[selectedRole].positions}<br>연결 포지션</p></div><h3 class="sub-heading">중점 반영할 능력치</h3><div class="priority-attributes">${Abilities.roles[selectedRole].keys.map(k=>`<span>${k}</span>`).join('')}</div><p class="prototype-note">가중치 비율은 미정입니다.<br>OVR은 미리 준비한 예시이며 실제 계산되지 않습니다.</p>`:updatePanel(p)}<div class="modal-actions">${btn('닫기','close','secondary')}</div>`)}
function updatePanel(p){const record=state.record,review=state.reviews[p.id],hasReview=review?.schema===2;return `<div class="update-intro"><span class="eyebrow">AFTER THE MATCH</span><h3>경기의 기록을, 다음 카드로.</h3><p>기록과 동료 평가를 모아 카드에 반영하는 흐름입니다.</p></div><ol class="update-steps"><li><b>01</b><div><strong>경기 기록</strong><p>${record?`${esc(record.opponent)} · ${esc(record.score)}`:'경기 결과와 선수별 골·어시스트 입력'}</p><button class="text-btn" data-action="record-match">${record?'기록 수정':'기록 입력'} <svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></button></div><span class="tag">${record?'입력됨':'대기'}</span></li><li><b>02</b><div><strong>동료 평가</strong><p>${hasReview?'이 선수의 평가가 데모로 저장되어 있습니다.':p.id===9?'내 평가는 동료가 작성합니다.':'관찰한 세부 능력치를 1–5점으로 평가'}</p><button class="text-btn" data-action="go-review" data-id="${p.id===9?101:p.id}">${p.id===9?'동료 평가 화면':'평가 작성'} <svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></button></div><span class="tag">${hasReview?'입력됨':'대기'}</span></li><li><b>03</b><div><strong>카드 반영 미리보기</strong><p>입력 내용 확인 후 변화 화면을 확인합니다.</p><button class="text-btn" data-action="update-preview" data-id="${p.id}">예시 미리보기 <svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></button></div><span class="tag">예시</span></li></ol><p class="prototype-note">입력은 이 브라우저에만 저장됩니다.<br>실제 능력치 및 OVR은 변경되지 않습니다.</p>`}
function updatePreview(id){if(getPlayer(id)?.managed)return pilotPlayerModal(id);const p=getPlayer(id),record=state.record,review=state.reviews[id],personal=record?.players?.[id];if($('#modal').open)closeModal();modal('카드 반영 미리보기',`<span class="tag">UI 시뮬레이션</span><h3 class="sub-heading">${p.name} · 반영 자료 확인</h3><div class="update-source"><strong>경기 기록</strong><p>${record?`${esc(record.opponent)} · ${esc(record.score)}`:'입력된 경기 기록 없음'}</p>${personal?`<p>${personal.goals}골 · ${personal.assists}도움</p>`:''}<strong>동료 평가</strong><p>${review?.schema===2?`${Abilities.schema(p).flatMap(a=>a[2]).filter(label=>review.attributes[label]!==undefined&&review.attributes[label]!=='').length}개 항목 관찰 완료`:'입력된 세부 평가 없음'}</p></div><div class="rating-transition"><div><span>현재 예시 카드</span><strong>${ratingText(p.ovr)}</strong></div><b>→</b><div><span>반영 후 화면 예시</span><strong>${p.demo.next}</strong></div></div><p class="note">위 변화는 고정된 디자인 예시입니다. 입력한 골·어시스트와 평가로 계산한 결과가 아니며, 현재 선수 카드는 바뀌지 않습니다.</p><div class="modal-actions"><button class="btn secondary" data-action="profile-tab" data-id="${id}" data-value="updates">돌아가기</button>${btn('미리보기 완료','close')}</div>`)}

function fixtureModal(f){modal('경기 상세',`<span class="tag">${esc(f.type)}</span><h2 style="font-size:20px;margin:23px 0">${ClubSettings.html('name')} <span style="color:#7a9068">vs</span> ${esc(f.opponent)}</h2><div class="summary-box"><strong>${esc(f.date)} · ${esc(f.time)}</strong>${esc(f.venue)} · ${esc(f.duration)}분 · 5인제</div><h3 class="sub-heading">출전 예정</h3><p class="note">${state.lineup.map(id=>getPlayer(id).name).join(' · ')}</p><p class="availability">● 등록 선수 ${players.length}명 모두 출전 가능</p><p class="note">데모 일정입니다. 실제 구장 예약 및 상대 팀 연락은 이루어지지 않습니다.</p><div class="modal-actions">${btn('닫기','close','secondary')}${btn('스쿼드 확인','goto-squad')}</div>`)}
function createMatch(){modal('새로운 경기 만들기',`<p class="note">상대 팀과 경기할 장소, 시간을 선택하세요.</p><form id="match-form"><p id="match-error" role="alert" class="form-error" hidden></p><label class="field">상대 팀<select name="opponent"><option>청룡 FC</option><option>번개 FC</option><option>독수리 FC</option></select></label><div class="two-fields"><label class="field">경기 날짜<input type="date" name="date" min="2026-11-01" value="2026-11-07" required></label><label class="field">시작 시간<input type="time" name="time" value="14:00" required></label></div><label class="field">구장<select name="venue"><option>제1풋살장</option><option>실내 풋살장</option><option>번개 풋살 파크</option></select></label><div class="two-fields"><label class="field">경기 유형<select name="type"><option>친선 경기</option><option>교류전</option><option>클럽 리그</option></select></label><label class="field">경기 시간<select name="duration"><option value="60">60분</option><option value="90">90분</option></select></label></div><p class="note">일정은 이 기기에만 저장됩니다. 상대 팀 전송 및 구장 예약 기능은 포함하지 않습니다.</p><div class="modal-actions">${btn('취소','close','secondary')}<button type="submit" class="btn">데모 일정 등록</button></div></form>`)}
function slotModal(slot){return SquadUI.slotModal(slot)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=Number(el.dataset.id),v=el.dataset.value;switch(a){case'profile-tab':playerModal(id,v);break;case'profile-role':playerModal(id,'roles',v);break;case'update-preview':updatePreview(id);break;case'go-review':reviewPlayer=id;closeModal();location.hash='reviews';render();break;case'menu':document.body.classList.toggle('menu-open');break;case'close':closeModal();break;case'player':if($('#modal').open)closeModal();playerModal(id);break;case'profile':playerModal(9);break;case'create-match':createMatch();break;case'match-detail':fixtureModal(baseFixtures[0]);break;case'fixture':fixtureModal(fixtures()[id]);break;case'day-fixtures':{const day=fixtures().filter(f=>f.date===el.dataset.date);if(day.length===1)fixtureModal(day[0]);else modal(el.dataset.date+' 경기',day.map(f=>`<button class="fixture-card" data-action="day-open" data-id="${fixtures().indexOf(f)}"><span class="fixture-info"><strong>${esc(f.time)} · ${esc(f.opponent)}</strong><small>${esc(f.venue)}</small></span><span><svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></button>`).join(''));break}case'day-open':closeModal();fixtureModal(fixtures()[id]);break;case'goto-squad':closeModal();location.hash='squad';break;case'formation':state.formation=v;save();render();toast(`${v} 포메이션으로 변경했습니다.`);break;case'best':state.lineup=players.slice(0,5).map(p=>p.id);save();render();toast('선발 라인업을 설정했습니다.');break;case'random':{const out=players.filter(p=>p.pos!=='GK').map(p=>p.id);for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}state.lineup=players.some(p=>p.pos==='GK')?[...out.slice(0,4),players.find(p=>p.pos==='GK').id]:out.slice(0,5);save();render();toast('골키퍼를 포함해 새 라인업을 편성했습니다.');break}case'save-squad':save();toast('스쿼드 저장을 요청했습니다. 상단의 공유 저장 상태를 확인하세요.');break;case'slot':slotModal(Number(el.dataset.slot));break;case'assign':{const slot=Number(el.dataset.slot),old=state.lineup.indexOf(id);if(old>=0)[state.lineup[old],state.lineup[slot]]=[state.lineup[slot],state.lineup[old]];else state.lineup[slot]=id;save();closeModal();render();toast('선수 배치를 변경했습니다.');break}case'sub':modal('교체할 선발 선수 선택',`<p class="note">${getPlayer(id).name} 선수를 투입할 위치를 선택하세요.</p>${state.lineup.slice(0,4).map((pid,i)=>`<div class="bench-row"><div><strong>${getPlayer(pid).name}</strong><small>${getPlayer(pid).pos}</small></div><button style="margin-left:auto" data-action="assign" data-id="${id}" data-slot="${i}">교체</button></div>`).join('')}`);break;case'filter':filter=v;render();break;case'prev-month':month--;if(month<1){month=12;year--}render();break;case'next-month':month++;if(month>12){month=1;year++}render();break;case'review-select':reviewPlayer=id;render();break;case'strategy':state.notes=$('#tactic-notes').value;state.strategy=v;const preset={balance:[60,65,55],attack:[80,90,70],possession:[55,40,75]}[v];[state.press,state.pace,state.width]=preset;render();toast('플레이 스타일을 적용했습니다. 저장 버튼으로 확정하세요.');break;case'save-tactics':state.notes=$('#tactic-notes').value;save();toast('전술과 메모를 저장했습니다.');break;case'notifications':modal('클럽 소식',`<div class="upcoming-item"><span class="tag">경기 알림</span><strong>6일 뒤, 청룡 FC와의 경기</strong><p>11월 7일 토요일 오후 2시 · 제1풋살장</p></div><div class="upcoming-item"><span class="tag">동료 평가</span><strong>지난 경기를 함께 돌아보세요.</strong><p>10월 31일 경기에 출전한 동료들의 평가를 남길 수 있습니다.</p><a href="#reviews" class="btn secondary" data-action="close">평가하러 가기</a></div>`);break;case'result-detail':location.hash='results';break;case'record-match':if($('#modal').open)closeModal();modal('경기 기록 입력',`<form id="record-form"><p class="note">완료한 경기의 결과와 선수별 기록을 입력하세요. 저장 후 동료 평가로 이어집니다.</p><label class="field">상대 팀<input name="opponent" required maxlength="40" placeholder="예: 청룡 FC" value="${esc(state.record?.opponent||'')}"></label><div class="two-fields"><label class="field">우리 팀 득점<input type="number" name="home" min="0" max="99" value="${esc(state.record?.score?.split(' : ')[0]||'0')}" required></label><label class="field">상대 팀 득점<input type="number" name="away" min="0" max="99" value="${esc(state.record?.score?.split(' : ')[1]||'0')}" required></label></div><details class="record-players" open><summary>선수별 골 · 어시스트</summary><div class="record-labels"><span>선수</span><span>골</span><span>어시스트</span></div>${players.map(p=>`<div class="record-player-row"><span>${p.name}<small>${p.pos}</small></span><input type="number" name="goals-${p.id}" aria-label="${p.name} 골" min="0" max="99" value="${state.record?.players?.[p.id]?.goals||0}" required><input type="number" name="assists-${p.id}" aria-label="${p.name} 어시스트" min="0" max="99" value="${state.record?.players?.[p.id]?.assists||0}" required></div>`).join('')}</details><label class="field">주요 기록 메모<textarea name="notes" rows="4" maxlength="500" placeholder="예: 빠른 역습으로 만든 선제골">${esc(state.record?.notes||'')}</textarea></label><div class="modal-actions">${btn('취소','close','secondary')}<button class="btn" type="submit">저장 후 동료 평가</button></div></form>`);break}});
document.addEventListener('input',e=>{if(e.target.dataset.output){document.getElementById(e.target.dataset.output).textContent=e.target.value;if(e.target.dataset.key)state[e.target.dataset.key]=Number(e.target.value)}if(e.target.id==='player-search'){search=e.target.value;const start=e.target.selectionStart;render();const input=$('#player-search');input.focus();if(input.setSelectionRange)input.setSelectionRange(start,start)}});
document.addEventListener('submit',e=>{if(!['match-form','review-form','record-form'].includes(e.target.id))return;e.preventDefault();const fd=new FormData(e.target);if(e.target.id==='match-form'){const f=Object.fromEntries(fd);const start=Date.parse(`${f.date}T${f.time}`),end=start+Number(f.duration)*60000;const conflict=fixtures().some(x=>{const s=Date.parse(`${x.date}T${x.time}`),en=s+Number(x.duration)*60000;return start<en&&end>s});if(conflict){$('#match-error').hidden=false;$('#match-error').textContent='같은 시간에 등록된 경기가 있습니다. 다른 시간을 선택해 주세요.';return}state.fixtures.push(f);save();year=Number(f.date.slice(0,4));month=Number(f.date.slice(5,7));closeModal();location.hash='matches';render();toast('데모 일정이 등록되었습니다. 실제 예약은 진행되지 않습니다.')}if(e.target.id==='review-form'){state.reviews[reviewPlayer]={schema:2,attributes:Object.fromEntries(Abilities.schema(getPlayer(reviewPlayer)).flatMap(a=>a[2]).map(label=>[label,String(fd.get(`ability:${label}`)||'')])),comment:fd.get('comment')};save();render();playerModal(reviewPlayer,'updates');toast('평가를 데모로 저장했습니다. 실제 능력치는 바뀌지 않습니다.')}if(e.target.id==='record-form'){state.record={opponent:fd.get('opponent'),score:`${fd.get('home')} : ${fd.get('away')}`,notes:fd.get('notes'),players:Object.fromEntries(players.map(p=>[p.id,{goals:Number(fd.get(`goals-${p.id}`)),assists:Number(fd.get(`assists-${p.id}`))}]))};save();closeModal();location.hash='reviews';render();toast('경기 기록을 데모로 저장했습니다. 동료 평가를 이어가세요.')}});

document.addEventListener('change',event=>{const id=event.target.dataset.inhousePosition;if(!id)return;const d=getInhouseDraft();d.positions[id]=event.target.value;d.saved=false;if(d.result)d.result.mode='manual';render();});
